const homedir = os.homedir();
const PROTECTED_EXTS = ['.git', '.env', '.key', '.pem', '.sln', '.docx', '.xlsx', '.pptx', '.rs', '.go'];
const PROTECTED_PATHS = ['c:/windows', 'c:/program files', path.join(homedir, 'Desktop/Projects').replace(/\\/g, '/').toLowerCase()];

const rawPath = (msg.payload && msg.payload.file_path) || '';
const resolvedPath = rawPath.replace(/%USERPROFILE%/i, homedir);
const normalizedPath = resolvedPath.replace(/\\/g, '/').toLowerCase();

// 檢查受保護副檔名 (包含 .env 相關檔)
const isProtectedExt = PROTECTED_EXTS.some(ext => normalizedPath.endsWith(ext) || normalizedPath.includes('/.env'));
// 檢查受保護目錄
const isProtectedPath = PROTECTED_PATHS.some(dir => normalizedPath.startsWith(dir));

if (isProtectedExt || isProtectedPath) {
    node.warn(`🛑 [安全攔截] 檔案「${rawPath}」為受保護核心資產，AI 絕對不可操作！`);

    // 記錄安全攔截審計日誌
    const auditDir = path.join(homedir, 'SystemLogs');
    fs.mkdirSync(auditDir, { recursive: true });
    const auditFile = path.join(auditDir, 'security_audit.log');
    const logLine = `[${new Date().toISOString()}] 操作: BLOCKED | 攔截目標: ${resolvedPath} | 原因: 命中核心白名單資產\n`;
    fs.appendFileSync(auditFile, logLine, 'utf-8');

    node.status({ fill: 'red', shape: 'ring', text: `已物理阻斷: ${path.basename(resolvedPath)}` });
    return null; // 物理阻斷，不流入下游
}

node.status({ fill: 'green', shape: 'dot', text: '通過安全白名單檢查' });
msg.payload.resolved_path = resolvedPath;
return msg;

const homedir = os.homedir();
const today = new Date().toISOString().slice(0, 10);
const quarantineDir = path.join(homedir, '.quarantine', today);
fs.mkdirSync(quarantineDir, { recursive: true });

const srcPath = msg.payload.resolved_path || (msg.payload.file_path || '').replace(/%USERPROFILE%/i, homedir);
const fileName = path.basename(srcPath);
const destPath = path.join(quarantineDir, fileName);

let status = 'SIMULATED_QUARANTINE';

// 以搬入隔離區代替物理刪除，保留 30 天反悔期
if (fs.existsSync(srcPath)) {
    fs.renameSync(srcPath, destPath);
    node.warn(`📦 [已安全隔離] 檔案已移入: ${destPath}`);
    status = 'QUARANTINED';
}

// 寫入審計追蹤日誌 (Audit Trail)
const auditDir = path.join(homedir, 'SystemLogs');
fs.mkdirSync(auditDir, { recursive: true });
const auditFile = path.join(auditDir, 'security_audit.log');
const logLine = `[${new Date().toISOString()}] 操作: ${status} | 原路徑: ${srcPath} | 隔離路徑: ${destPath}\n`;
fs.appendFileSync(auditFile, logLine, 'utf-8');

node.status({ fill: 'blue', shape: 'dot', text: `已隔離: ${fileName}` });
msg.payload = {
    status: status,
    original: srcPath,
    current: destPath,
    audit_logged: true,
    retention_days: 30
};

return msg;
